import React from "react";

const STATS = [
  { key: "balance",    label: "Balance",          icon: "🏦", accent: "#63b3ed" },
  { key: "income",     label: "Total Income",      icon: "📈", accent: "#68d391" },
  { key: "expense",    label: "Total Expense",     icon: "📉", accent: "#fc8181" },
  { key: "investment", label: "Investment",        icon: "💼", accent: "#b794f4" },
  { key: "cash",       label: "Cash on Hand",      icon: "💵", accent: "#f6e05e" },
  { key: "borrow",     label: "Net Borrowed",      icon: "🤝", accent: "#f6ad55" },
];

export default function Summary({ entries }) {
  const filtered = entries.filter(e => e.category !== "Bank Transfer");

  const income     = filtered.filter(e => e.type === "income").reduce((s,e) => s + e.amount, 0);
  const expense    = filtered.filter(e => e.type === "expense").reduce((s,e) => s + e.amount, 0);
  const investment = filtered.filter(e => e.type === "investment").reduce((s,e) => s + e.amount, 0);
  const balance    = income - expense - investment;

  const cashIn  = entries.filter(e => e.bank === "CASH" && e.type === "income").reduce((s,e) => s + (e.amount||0), 0);
  const cashOut = entries.filter(e => e.bank === "CASH" && e.type === "expense").reduce((s,e) => s + (e.amount||0), 0);
  const cash    = cashIn - cashOut;

  const borrowed = entries.filter(e => e.type === "borrow").reduce((s,e) => s + (e.amount||0), 0)
                 - entries.filter(e => e.type === "borrowReturn").reduce((s,e) => s + (e.amount||0), 0);

  const vals = { balance, income, expense, investment, cash, borrow: borrowed };
  const fmt  = n => `₹${Math.abs(n).toLocaleString("en-IN", { minimumFractionDigits: 2 })}`;

  return (
    <div style={{ display:"grid", gridTemplateColumns:"repeat(3,1fr)", gap:10, marginBottom:20 }}
         className="summary-grid">
      {STATS.map(s => {
        const val = vals[s.key];
        const isNeg = val < 0;
        return (
          <div key={s.key} className="stat-card card"
            style={{ border:`1px solid ${s.accent}25 !important` }}>
            <div className="stat-card-glow" style={{ background: s.accent }} />
            <div style={{ position:"relative" }}>
              <div style={{
                width:36, height:36, borderRadius:9,
                background:`${s.accent}18`,
                display:"flex", alignItems:"center", justifyContent:"center",
                fontSize:17, marginBottom:9,
              }}>{s.icon}</div>
              <div className="stat-label">{s.label}</div>
              <div className="stat-value" style={{ color: isNeg ? "var(--accent-red)" : s.accent }}>
                {isNeg ? "-" : ""}{fmt(val)}
              </div>
            </div>
          </div>
        );
      })}
      <style>{`
        @media (max-width: 576px) {
          .summary-grid { grid-template-columns: repeat(2, 1fr) !important; gap: 8px !important; }
          .stat-value { font-size: 14px !important; }
        }
        @media (min-width: 992px) {
          .summary-grid { grid-template-columns: repeat(6, 1fr) !important; }
        }
      `}</style>
    </div>
  );
}