import React, { useState } from "react";
import { BsTrash } from "react-icons/bs";
import Swal from "sweetalert2";

const TYPE_COLOR = { income:"#68d391", expense:"#fc8181", investment:"#63b3ed", borrow:"#b794f4", borrowReturn:"#f6e05e" };
const TYPE_BG    = { income:"rgba(104,211,145,0.12)", expense:"rgba(252,129,129,0.12)", investment:"rgba(99,179,237,0.12)", borrow:"rgba(183,148,244,0.12)", borrowReturn:"rgba(246,224,94,0.12)" };
const TYPE_LABEL = { income:"Income", expense:"Expense", investment:"Investment", borrow:"Borrow", borrowReturn:"Borrow Return" };

function Badge({ type }) {
  return (
    <span className="type-badge" style={{
      background: TYPE_BG[type]    || "rgba(255,255,255,0.08)",
      color:      TYPE_COLOR[type] || "var(--text-primary)",
      border:     `1px solid ${(TYPE_COLOR[type]||"#fff")}35`,
    }}>
      {TYPE_LABEL[type] || type}
    </span>
  );
}

export default function EntriesList({ entries, deleteEntry }) {
  const [sort,       setSort]       = useState({ key:"date", dir:"desc" });
  const [filterType, setFilterType] = useState("");
  const [filterBank, setFilterBank] = useState("");
  const [page,       setPage]       = useState(1);
  const PER_PAGE = 10;

  const sorted = [...entries]
    .filter(e => filterType ? e.type === filterType : true)
    .filter(e => filterBank ? e.bank === filterBank : true)
    .sort((a,b) => {
      let A = a[sort.key], B = b[sort.key];
      if (sort.key === "amount") { A = +A; B = +B; }
      else if (sort.key === "date") { A = new Date(A); B = new Date(B); }
      else { A = A?.toString().toLowerCase()||""; B = B?.toString().toLowerCase()||""; }
      return A < B ? (sort.dir==="asc"?-1:1) : A > B ? (sort.dir==="asc"?1:-1) : 0;
    });

  const totalPages = Math.ceil(sorted.length / PER_PAGE) || 1;
  const paged      = sorted.slice((page-1)*PER_PAGE, page*PER_PAGE);
  const total      = sorted.reduce((s,e) => s + e.amount, 0);

  const requestSort = key => {
    setSort(prev => ({ key, dir: prev.key===key && prev.dir==="asc" ? "desc" : "asc" }));
    setPage(1);
  };
  const SortArrow = ({ k }) => sort.key===k
    ? <span style={{ color:"var(--accent-blue)", marginLeft:3 }}>{sort.dir==="asc"?"↑":"↓"}</span>
    : <span style={{ color:"var(--text-muted)", marginLeft:3, fontSize:10 }}>↕</span>;

  const uniqueTypes = [...new Set(entries.map(e => e.type))];
  const uniqueBanks = [...new Set(entries.map(e => e.bank).filter(Boolean))];

  const doDelete = id => {
    Swal.fire({
      title:"Delete entry?", text:"This cannot be undone.", icon:"warning",
      showCancelButton:true, confirmButtonColor:"#e53e3e", cancelButtonColor:"#4a5568",
      confirmButtonText:"Delete", background:"var(--bg-surface)", color:"var(--text-primary)",
    }).then(r => {
      if (r.isConfirmed) {
        deleteEntry(id);
        Swal.fire({ title:"Deleted", icon:"success", timer:1300, showConfirmButton:false,
          background:"var(--bg-surface)", color:"var(--text-primary)" });
      }
    });
  };

  return (
    <div className="card">
      <div className="card-body">
        {/* Header row */}
        <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", flexWrap:"wrap", gap:10, marginBottom:14 }}>
          <div style={{ display:"flex", alignItems:"center", gap:10 }}>
            <h5 style={{ margin:0, fontFamily:"'Syne',sans-serif", fontWeight:700 }}>All Entries</h5>
            <span style={{ background:"rgba(99,179,237,0.14)", color:"var(--accent-blue)", borderRadius:20, padding:"2px 10px", fontSize:12, fontWeight:700 }}>
              {sorted.length}
            </span>
          </div>
          {/* Filters */}
          <div style={{ display:"flex", gap:8, flexWrap:"wrap" }}>
            <select className="form-select" style={{ width:"auto", minWidth:130 }} value={filterType}
              onChange={e => { setFilterType(e.target.value); setPage(1); }}>
              <option value="">All Types</option>
              {uniqueTypes.map((t,i) => <option key={i} value={t}>{TYPE_LABEL[t]||t}</option>)}
            </select>
            <select className="form-select" style={{ width:"auto", minWidth:110 }} value={filterBank}
              onChange={e => { setFilterBank(e.target.value); setPage(1); }}>
              <option value="">All Banks</option>
              {uniqueBanks.map((b,i) => <option key={i} value={b}>{b}</option>)}
            </select>
          </div>
        </div>

        {/* Mobile card list */}
        <div className="entries-mobile" style={{ display:"none" }}>
          {paged.length === 0
            ? <div style={{ textAlign:"center", padding:"40px 0", color:"var(--text-muted)" }}>📭 No entries</div>
            : paged.map(entry => (
              <div key={entry.id} style={{
                background:"var(--bg-input)", borderRadius:12, padding:"12px 14px",
                marginBottom:8, border:"1px solid var(--border)",
                display:"flex", justifyContent:"space-between", alignItems:"flex-start",
              }}>
                <div style={{ flex:1, minWidth:0 }}>
                  <div style={{ display:"flex", alignItems:"center", gap:6, marginBottom:4, flexWrap:"wrap" }}>
                    <Badge type={entry.type} />
                    <span style={{ fontSize:11, color:"var(--text-muted)" }}>{entry.date}</span>
                    <span style={{ fontSize:11, background:"rgba(255,255,255,0.06)", borderRadius:5, padding:"1px 7px", color:"var(--text-secondary)" }}>
                      {entry.bank}
                    </span>
                  </div>
                  <div style={{ fontSize:13, color:"var(--text-primary)", fontWeight:500, whiteSpace:"nowrap", overflow:"hidden", textOverflow:"ellipsis" }}>
                    {entry.description}
                  </div>
                  <div style={{ fontSize:11, color:"var(--text-secondary)", marginTop:2 }}>{entry.category}</div>
                </div>
                <div style={{ display:"flex", flexDirection:"column", alignItems:"flex-end", gap:6, marginLeft:10 }}>
                  <span style={{ fontWeight:800, fontSize:15, color: TYPE_COLOR[entry.type]||"var(--text-primary)" }}>
                    ₹{entry.amount.toFixed(2)}
                  </span>
                  <button className="btn btn-sm btn-danger" style={{ padding:"4px 8px" }} onClick={() => doDelete(entry.id)}>
                    <BsTrash size={12} />
                  </button>
                </div>
              </div>
            ))
          }
        </div>

        {/* Desktop table */}
        <div className="entries-table" style={{ overflowX:"auto" }}>
          {paged.length === 0
            ? <div style={{ textAlign:"center", padding:"48px 0", color:"var(--text-muted)" }}>
                <div style={{ fontSize:36, marginBottom:8 }}>📭</div>
                No entries found
              </div>
            : <table className="table table-hover" style={{ whiteSpace:"nowrap", minWidth:550 }}>
                <thead className="table-dark">
                  <tr>
                    {[["date","Date"],["type","Type"],["description","Description"],["category","Category"],["bank","Bank"],["amount","Amount"]].map(([k,l]) => (
                      <th key={k} onClick={() => requestSort(k)} style={{ cursor:"pointer", userSelect:"none" }}>
                        {l}<SortArrow k={k} />
                      </th>
                    ))}
                    <th>Del</th>
                  </tr>
                </thead>
                <tbody>
                  {paged.map(entry => (
                    <tr key={entry.id}>
                      <td style={{ color:"var(--text-secondary)", fontSize:12 }}>{entry.date}</td>
                      <td><Badge type={entry.type} /></td>
                      <td style={{ maxWidth:160, overflow:"hidden", textOverflow:"ellipsis" }}>{entry.description}</td>
                      <td style={{ color:"var(--text-secondary)" }}>{entry.category}</td>
                      <td><span style={{ background:"rgba(255,255,255,0.06)", borderRadius:5, padding:"2px 8px", fontSize:12 }}>{entry.bank||"-"}</span></td>
                      <td style={{ fontWeight:700, color: TYPE_COLOR[entry.type]||"var(--text-primary)" }}>
                        ₹{entry.amount.toFixed(2)}
                      </td>
                      <td>
                        <button className="btn btn-sm btn-danger" style={{ padding:"4px 8px" }} onClick={() => doDelete(entry.id)}>
                          <BsTrash size={13} />
                        </button>
                      </td>
                    </tr>
                  ))}
                  <tr>
                    <td colSpan="5" style={{ textAlign:"right", fontFamily:"'Syne',sans-serif", fontWeight:700, fontSize:11, letterSpacing:"0.06em", textTransform:"uppercase", color:"var(--text-secondary)" }}>
                      Total ({sorted.length} entries)
                    </td>
                    <td style={{ fontWeight:800, fontSize:15, color:"var(--text-primary)" }}>₹{total.toFixed(2)}</td>
                    <td />
                  </tr>
                </tbody>
              </table>
          }
        </div>

        {/* Pagination */}
        <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginTop:12, flexWrap:"wrap", gap:8 }}>
          <span style={{ color:"var(--text-secondary)", fontSize:12 }}>
            Page {page} of {totalPages} · {sorted.length} entries
          </span>
          <div style={{ display:"flex", gap:6 }}>
            <button className="btn btn-sm btn-outline-primary" disabled={page===1} onClick={() => setPage(p=>p-1)}>← Prev</button>
            {Array.from({length:Math.min(5,totalPages)}, (_,i) => {
              const p = page <= 3 ? i+1 : page + i - 2;
              if (p < 1 || p > totalPages) return null;
              return (
                <button key={p} className="btn btn-sm" onClick={() => setPage(p)}
                  style={{ background: p===page ? "var(--accent-blue)" : "var(--bg-input)", color: p===page ? "#fff" : "var(--text-secondary)", border:"1px solid var(--border)", borderRadius:8, minWidth:32 }}>
                  {p}
                </button>
              );
            })}
            <button className="btn btn-sm btn-outline-primary" disabled={page===totalPages} onClick={() => setPage(p=>p+1)}>Next →</button>
          </div>
        </div>
      </div>

      <style>{`
        @media (max-width: 600px) {
          .entries-mobile { display: block !important; }
          .entries-table  { display: none; }
        }
      `}</style>
    </div>
  );
}