import React, { useState } from "react";
import Swal from "sweetalert2";

const BANKS = ["BOB", "ICICI", "CASH"];

const CATEGORIES = {
  income:       ["Salary","Bonus","Freelance","Other"],
  expense:      ["Food","Rent","Travel","Utilities","Other"],
  investment:   ["Stocks","Mutual Fund","Other"],
  borrow:       ["Borrow"],
  borrowReturn: ["Return"],
};

const TYPE_META = {
  income:       { label:"Income",       icon:"📈", accent:"#68d391" },
  expense:      { label:"Expense",      icon:"📉", accent:"#fc8181" },
  investment:   { label:"Investment",   icon:"💼", accent:"#63b3ed" },
  borrow:       { label:"Borrow",       icon:"🤝", accent:"#b794f4" },
  borrowReturn: { label:"Borrow Return",icon:"↩️", accent:"#f6e05e" },
};

export default function EntryForm({ addEntry }) {
  const [type,        setType]        = useState("income");
  const [description, setDescription] = useState("");
  const [amount,      setAmount]      = useState("");
  const [category,    setCategory]    = useState("");
  const [bank,        setBank]        = useState(BANKS[0]);
  const [date,        setDate]        = useState(new Date().toISOString().split("T")[0]);

  const handleSubmit = (e) => {
    e.preventDefault();
    if (!description || !amount || !category || !bank) {
      return Swal.fire({ icon:"error", title:"Missing fields", text:"Please fill all fields", background:"var(--bg-surface)", color:"var(--text-primary)" });
    }
    addEntry({ id: Date.now(), type, description, amount: parseFloat(amount), category, bank, date });
    Swal.fire({ icon:"success", title:"Entry Added!", timer:1600, showConfirmButton:false, background:"var(--bg-surface)", color:"var(--text-primary)" });
    setDescription(""); setAmount(""); setCategory("");
  };

  const { accent } = TYPE_META[type];

  return (
    <div className="card" style={{ borderColor:`${accent}35` }}>
      <div className="card-header" style={{ background:`linear-gradient(135deg,${accent}1a,${accent}08)`, borderBottomColor:`${accent}22` }}>
        <div style={{ display:"flex", alignItems:"center", gap:8 }}>
          <div style={{ width:8, height:8, borderRadius:"50%", background:accent, boxShadow:`0 0 8px ${accent}` }} />
          <h5 style={{ margin:0, color:accent }}>Add New Entry</h5>
        </div>
      </div>
      <div className="card-body">

        {/* Quick Shortcuts */}
        <div style={{ display:"flex", gap:8, marginBottom:16, flexWrap:"wrap" }}>
          <button type="button" className="btn btn-outline-danger btn-sm" style={{ flex:1, minWidth:130 }}
            onClick={() => { setBank("CASH"); setType("expense"); setDescription("Cash withdrawal (ATM)"); setCategory("Other"); }}>
            💸 ATM Withdraw
          </button>
          <button type="button" className="btn btn-outline-success btn-sm" style={{ flex:1, minWidth:130 }}
            onClick={() => { setBank("CASH"); setType("income"); setDescription("Cash received"); setCategory("Other"); }}>
            💵 Cash Received
          </button>
        </div>

        {/* Type pills */}
        <div style={{ marginBottom:18 }}>
          <label className="form-label">Transaction Type</label>
          <div style={{ display:"flex", flexWrap:"wrap", gap:7, marginTop:2 }}>
            {Object.entries(TYPE_META).map(([t, meta]) => (
              <button key={t} type="button"
                onClick={() => { setType(t); setCategory(""); }}
                className="pill-tab"
                style={{
                  borderColor: meta.accent,
                  color: type === t ? meta.accent : "var(--text-muted)",
                  background: type === t ? `${meta.accent}18` : "transparent",
                }}>
                {meta.icon} {meta.label}
              </button>
            ))}
          </div>
        </div>

        <form onSubmit={handleSubmit}>
          <div style={{ display:"grid", gridTemplateColumns:"repeat(auto-fill,minmax(160px,1fr))", gap:12, alignItems:"end" }}
               className="entry-form-grid">

            <div>
              <label className="form-label">Description</label>
              <input type="text" className="form-control" value={description}
                onChange={e => setDescription(e.target.value)} placeholder="What was this?" />
            </div>

            <div>
              <label className="form-label">Amount (₹)</label>
              <input type="number" className="form-control" value={amount} min="0" step="0.01"
                onChange={e => setAmount(e.target.value)} placeholder="0.00" />
            </div>

            <div>
              <label className="form-label">Category</label>
              <select className="form-select" value={category} onChange={e => setCategory(e.target.value)}>
                <option value="">Select…</option>
                {CATEGORIES[type].map((c,i) => <option key={i} value={c}>{c}</option>)}
              </select>
            </div>

            <div>
              <label className="form-label">Bank / Wallet</label>
              <select className="form-select" value={bank} onChange={e => setBank(e.target.value)}>
                {BANKS.map((b,i) => <option key={i} value={b}>{b}</option>)}
              </select>
            </div>

            <div>
              <label className="form-label">Date</label>
              <input type="date" className="form-control" value={date} onChange={e => setDate(e.target.value)} />
            </div>

            <div style={{ display:"flex", alignItems:"flex-end" }}>
              <button type="submit" className="btn btn-success" style={{ width:"100%",
                background:`linear-gradient(135deg,${accent},${accent}bb)`,
                boxShadow:`0 4px 14px ${accent}30` }}>
                + Add Entry
              </button>
            </div>
          </div>
        </form>
      </div>
    </div>
  );
}