import React, { useState, useEffect } from "react";
import {
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend,
  ResponsiveContainer, LineChart, Line, PieChart, Pie, Cell, RadarChart,
  Radar, PolarGrid, PolarAngleAxis, PolarRadiusAxis, AreaChart, Area
} from "recharts";

const COLORS_PIE = ["#68d391","#fc8181","#63b3ed","#b794f4","#f6ad55","#4fd1c5"];

const CustomTooltip = ({ active, payload, label }) => {
  if (!active || !payload?.length) return null;
  return (
    <div style={{
      background:"var(--bg-surface)", border:"1px solid var(--border)",
      borderRadius:10, padding:"10px 14px", fontSize:12,
    }}>
      <p style={{ fontFamily:"'Syne',sans-serif", fontWeight:700, color:"var(--text-primary)", marginBottom:6 }}>{label}</p>
      {payload.map((p,i) => (
        <div key={i} style={{ color:p.color, marginBottom:2 }}>
          {p.name}: <strong>₹{(p.value||0).toLocaleString("en-IN",{minimumFractionDigits:2})}</strong>
        </div>
      ))}
    </div>
  );
};

export default function Dashboard({ entries, theme }) {
  const [monthData,   setMonthData]   = useState([]);
  const [bankData,    setBankData]    = useState([]);
  const [totalBalance,setTotalBalance]= useState(0);
  const [catExpense,  setCatExpense]  = useState([]);
  const [netWorthData,setNetWorthData]= useState([]);

  useEffect(() => {
    // ── Month-wise
    const realEntries = entries.filter(e =>
      e.category !== "Bank Transfer" || e.bank === "CASH"
    );
    const mg = {};
    realEntries.forEach(e => {
      const m = new Date(e.date).toLocaleString("default",{month:"short",year:"numeric"});
      if (!mg[m]) mg[m] = { name:m, income:0, expense:0, investment:0, borrow:0 };
      if (e.type === "borrow") mg[m].borrow += e.amount;
      else if (mg[m][e.type] !== undefined) mg[m][e.type] += e.amount;
    });
    const sorted = Object.values(mg).sort((a,b) => new Date("1 "+a.name) - new Date("1 "+b.name));
    setMonthData(sorted);

    // ── Cumulative net worth (area chart)
    let running = 0;
    const nw = sorted.map(m => {
      running += (m.income||0) - (m.expense||0) - (m.investment||0);
      return { name: m.name, netWorth: parseFloat(running.toFixed(2)) };
    });
    setNetWorthData(nw);

    // ── Bank-wise
    const bg = {};
    entries.forEach(e => {
      const b = e.bank || "Unknown";
      if (!bg[b]) bg[b] = { name:b, income:0, expense:0, investment:0, borrow:0, borrowReturn:0 };
      if (e.type === "borrow") bg[b].borrow += e.amount;
      else if (bg[b][e.type] !== undefined) bg[b][e.type] += e.amount;
    });
    const banks = Object.values(bg).map(bk => ({
      ...bk,
      balance: (bk.income + (bk.borrowReturn||0)) - (bk.expense + bk.investment + bk.borrow),
    }));
    setBankData(banks);
    setTotalBalance(banks.reduce((s,b) => s + b.balance, 0));

    // ── Category-wise expense (pie)
    const cg = {};
    entries.filter(e => e.type === "expense" && e.category !== "Bank Transfer").forEach(e => {
      cg[e.category] = (cg[e.category]||0) + e.amount;
    });
    setCatExpense(Object.entries(cg).map(([name,value]) => ({ name, value: parseFloat(value.toFixed(2)) })));

  }, [entries]);

  const fmt = n => `₹${(n||0).toLocaleString("en-IN",{minimumFractionDigits:2})}`;

  const chartHeight = 260;
  const cardStyle = { marginBottom:16 };

  return (
    <div>
      <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", marginBottom:16, flexWrap:"wrap", gap:8 }}>
        <h2 style={{ margin:0, fontSize:20 }}>Dashboard</h2>
        <div style={{
          padding:"8px 18px", borderRadius:10,
          background:"rgba(79,209,197,0.1)", border:"1px solid rgba(79,209,197,0.25)",
          color:"var(--accent-teal)", fontFamily:"'Syne',sans-serif", fontWeight:700, fontSize:14,
        }}>
          Net Balance: <span style={{ color:"var(--text-primary)" }}>{fmt(totalBalance)}</span>
        </div>
      </div>

      {/* ── Row 1: Monthly bar + Area net worth ── */}
      <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:12, marginBottom:12 }} className="dash-grid-2">
        <div className="card" style={cardStyle}>
          <div className="card-body">
            <p className="card-title">📅 Monthly Income vs Expense</p>
            <ResponsiveContainer width="100%" height={chartHeight}>
              <BarChart data={monthData} margin={{top:4,right:10,left:-10,bottom:0}}>
                <CartesianGrid strokeDasharray="3 3" />
                <XAxis dataKey="name" tick={{fontSize:10}} />
                <YAxis tick={{fontSize:10}} />
                <Tooltip content={<CustomTooltip />} />
                <Legend iconSize={10} wrapperStyle={{fontSize:11}} />
                <Bar dataKey="income"     fill="#68d391" radius={[4,4,0,0]} />
                <Bar dataKey="expense"    fill="#fc8181" radius={[4,4,0,0]} />
                <Bar dataKey="investment" fill="#63b3ed" radius={[4,4,0,0]} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="card" style={cardStyle}>
          <div className="card-body">
            <p className="card-title">📈 Net Worth Over Time</p>
            <ResponsiveContainer width="100%" height={chartHeight}>
              <AreaChart data={netWorthData} margin={{top:4,right:10,left:-10,bottom:0}}>
                <defs>
                  <linearGradient id="nwGrad" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%"  stopColor="#68d391" stopOpacity={0.25} />
                    <stop offset="95%" stopColor="#68d391" stopOpacity={0.02} />
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" />
                <XAxis dataKey="name" tick={{fontSize:10}} />
                <YAxis tick={{fontSize:10}} />
                <Tooltip content={<CustomTooltip />} />
                <Area type="monotone" dataKey="netWorth" stroke="#68d391" strokeWidth={2.5} fill="url(#nwGrad)" dot={{ r:3, fill:"#68d391" }} />
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>

      {/* ── Row 2: Pie (category expense) + Radar (bank) ── */}
      <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:12, marginBottom:12 }} className="dash-grid-2">
        <div className="card" style={cardStyle}>
          <div className="card-body">
            <p className="card-title">🍕 Expense by Category</p>
            {catExpense.length === 0
              ? <div style={{ textAlign:"center", padding:"60px 0", color:"var(--text-muted)" }}>No expense data</div>
              : <ResponsiveContainer width="100%" height={chartHeight}>
                  <PieChart>
                    <Pie data={catExpense} cx="50%" cy="50%" innerRadius={55} outerRadius={95}
                      paddingAngle={3} dataKey="value" nameKey="name"
                      label={({name,percent}) => `${name} ${(percent*100).toFixed(0)}%`}
                      labelLine={false}>
                      {catExpense.map((_,i) => <Cell key={i} fill={COLORS_PIE[i % COLORS_PIE.length]} />)}
                    </Pie>
                    <Tooltip content={<CustomTooltip />} />
                  </PieChart>
                </ResponsiveContainer>
            }
          </div>
        </div>

        <div className="card" style={cardStyle}>
          <div className="card-body">
            <p className="card-title">🏦 Bank-wise Activity (Radar)</p>
            {bankData.length === 0
              ? <div style={{ textAlign:"center", padding:"60px 0", color:"var(--text-muted)" }}>No bank data</div>
              : <ResponsiveContainer width="100%" height={chartHeight}>
                  <RadarChart data={bankData}>
                    <PolarGrid stroke="var(--border)" />
                    <PolarAngleAxis dataKey="name" tick={{fontSize:11, fill:"var(--text-secondary)"}} />
                    <PolarRadiusAxis tick={{fontSize:9, fill:"var(--text-secondary)"}} />
                    <Radar name="Income"     dataKey="income"     stroke="#68d391" fill="#68d391" fillOpacity={0.18} />
                    <Radar name="Expense"    dataKey="expense"    stroke="#fc8181" fill="#fc8181" fillOpacity={0.15} />
                    <Radar name="Investment" dataKey="investment" stroke="#63b3ed" fill="#63b3ed" fillOpacity={0.15} />
                    <Legend iconSize={10} wrapperStyle={{fontSize:11}} />
                  </RadarChart>
                </ResponsiveContainer>
            }
          </div>
        </div>
      </div>

      {/* ── Row 3: Monthly line trend ── */}
      <div className="card" style={{ ...cardStyle, marginBottom:12 }}>
        <div className="card-body">
          <p className="card-title">📊 Monthly Trend Lines</p>
          <ResponsiveContainer width="100%" height={220}>
            <LineChart data={monthData} margin={{top:4,right:10,left:-10,bottom:0}}>
              <CartesianGrid strokeDasharray="3 3" />
              <XAxis dataKey="name" tick={{fontSize:10}} />
              <YAxis tick={{fontSize:10}} />
              <Tooltip content={<CustomTooltip />} />
              <Legend iconSize={10} wrapperStyle={{fontSize:11}} />
              <Line type="monotone" dataKey="income"     stroke="#68d391" strokeWidth={2.5} dot={{ r:3 }} />
              <Line type="monotone" dataKey="expense"    stroke="#fc8181" strokeWidth={2.5} dot={{ r:3 }} />
              <Line type="monotone" dataKey="investment" stroke="#63b3ed" strokeWidth={2.5} dot={{ r:3 }} />
            </LineChart>
          </ResponsiveContainer>
        </div>
      </div>

      {/* ── Bank-wise table ── */}
      <div className="card" style={cardStyle}>
        <div className="card-body">
          <p className="card-title">🏧 Bank-wise Summary</p>
          <div className="table-responsive">
            <table className="table table-bordered table-hover">
              <thead>
                <tr>
                  {["Bank","Income","Expense","Investment","Borrow","Borrow Return","Balance"].map(h => (
                    <th key={h}>{h}</th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {bankData.length === 0
                  ? <tr><td colSpan="7" style={{ textAlign:"center", color:"var(--text-muted)" }}>No data</td></tr>
                  : bankData.map(b => (
                    <tr key={b.name}>
                      <td style={{ fontWeight:700 }}>{b.name}</td>
                      <td style={{ color:"var(--accent-green)" }}>{fmt(b.income)}</td>
                      <td style={{ color:"var(--accent-red)" }}>{fmt(b.expense)}</td>
                      <td style={{ color:"var(--accent-blue)" }}>{fmt(b.investment)}</td>
                      <td style={{ color:"var(--accent-purple)" }}>{fmt(b.borrow)}</td>
                      <td style={{ color:"var(--accent-teal)" }}>{fmt(b.borrowReturn)}</td>
                      <td style={{ fontWeight:800, color: b.balance >= 0 ? "var(--accent-green)" : "var(--accent-red)" }}>
                        {fmt(b.balance)}
                      </td>
                    </tr>
                  ))
                }
              </tbody>
            </table>
          </div>
        </div>
      </div>

      <style>{`
        @media (max-width: 640px) {
          .dash-grid-2 { grid-template-columns: 1fr !important; }
        }
        .card-title { font-family:'Syne',sans-serif; font-weight:700; font-size:14px; color:var(--text-primary); margin-bottom:14px !important; }
      `}</style>
    </div>
  );
}