import React, { useState, useRef, useEffect, useMemo, useCallback } from "react";
import { Client } from "@gradio/client";
import ReactMarkdown from "react-markdown";

const QUICK_PROMPTS = [
  "📊 Monthly summary",
  "💸 Top expenses",
  "🏦 Bank balances",
  "💡 Saving tips",
  "📈 Income vs Expense",
  "🤝 Borrow status",
];

const ChatAI = ({ entries }) => {
  const [userMessage, setUserMessage] = useState("");
  const [chatHistory, setChatHistory] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const chatEndRef = useRef(null);
  const clientRef = useRef(null);
  const abortControllerRef = useRef(null);
  const inputRef = useRef(null);

  const processedEntries = useMemo(() => {
    if (!entries || entries.length === 0) return [];
    const MAX_ENTRIES = 500;
    if (entries.length > MAX_ENTRIES) return entries.slice(-MAX_ENTRIES);
    return entries;
  }, [entries]);

  useEffect(() => {
    const initClient = async () => {
      try {
        if (!clientRef.current) {
          clientRef.current = await Client.connect("shivamsharmav/financetraker");
        }
      } catch (err) {
        console.error("Client init failed:", err);
        setError("Failed to connect to AI service");
      }
    };
    initClient();
    return () => { if (abortControllerRef.current) abortControllerRef.current.abort(); };
  }, []);

  const sendMessage = useCallback(async (msgOverride) => {
    const msg = msgOverride || userMessage;
    if (!msg.trim() || loading) return;

    setLoading(true);
    setError(null);

    const ts = new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
    setChatHistory(prev => [...prev, { sender: "user", text: msg, time: ts }]);
    setUserMessage("");

    abortControllerRef.current = new AbortController();

    try {
      const client = clientRef.current || await Client.connect("shivamsharmav/financetraker");
      const dataPayload = JSON.stringify(processedEntries);

      const result = await client.predict("/chat", {
        message: `Data: ${dataPayload}\nQuestion: ${msg}`,
        system_message: `
You are a Smart Finance Assistant AI.
You only use the provided JSON data to analyze the user's finances.

The JSON contains records like income, expense, borrow, borrowReturn, transfer, and investment with fields:
- id, type, description, amount, category, bank, date.

**Borrow / BorrowReturn Handling:**
- borrow → Money the user lent to someone. Reduces available balance. Not income.
- borrowReturn → Money received back. Increases available balance. Treated as cash inflow.
- Net effect on balance = borrowReturn - borrow

Your tasks:
1. Data Accuracy — Only calculate using the JSON data. Respect the "bank" field for bank-wise balance. If data missing, say "Data not available."
2. Financial Insights — Show totals, balances, summaries (daily, monthly, yearly). Compare categories. Highlight high-spending categories. Point out if spending > income in any month.
3. Advisory Suggestions — Suggest practical ways to reduce expenses. Suggest savings opportunities.
4. Formatting — Use Markdown: **Bold** for key numbers, bullet points for breakdowns, tables for comparisons. Always use ₹ symbol.

Keep responses structured, concise, and insightful like a financial advisor.
`,
        max_tokens: 1500,
        temperature: 0.3,
        top_p: 0.5,
      });

      const aiTs = new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
      const aiText = Array.isArray(result.data) ? result.data.join("\n") : result.data;
      setChatHistory(prev => [...prev, { sender: "ai", text: aiText, time: aiTs }]);
    } catch (err) {
      let msg2 = "Error fetching response.";
      if (err.name === "AbortError") msg2 = "Request was cancelled.";
      else if (err.message?.includes("timeout")) msg2 = "Request timed out. Please try again.";
      else if (err.message?.includes("network")) msg2 = "Network error. Check your connection.";
      setChatHistory(prev => [...prev, { sender: "ai", text: `❌ ${msg2}`, time: new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" }) }]);
      setError(msg2);
    } finally {
      setLoading(false);
      abortControllerRef.current = null;
    }
  }, [userMessage, loading, processedEntries]);

  useEffect(() => {
    const t = setTimeout(() => chatEndRef.current?.scrollIntoView({ behavior: "smooth" }), 80);
    return () => clearTimeout(t);
  }, [chatHistory]);

  const handleKeyDown = useCallback((e) => {
    if (e.key === "Enter" && !e.shiftKey) { e.preventDefault(); sendMessage(); }
  }, [sendMessage]);

  return (
    <div style={{
      borderRadius: 18,
      border: "1px solid var(--border)",
      background: "var(--bg-card)",
      backdropFilter: "blur(14px)",
      display: "flex",
      flexDirection: "column",
      height: "78vh",
      minHeight: 400,
      overflow: "hidden",
      boxShadow: "0 8px 32px rgba(0,0,0,0.35)",
    }}>

      {/* ── HEADER ── */}
      <div style={{
        padding: "13px 18px",
        background: "linear-gradient(135deg, rgba(90,141,238,0.25), rgba(66,230,149,0.18))",
        borderBottom: "1px solid var(--border)",
        display: "flex", alignItems: "center", justifyContent: "space-between",
      }}>
        <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
          <div style={{
            width: 36, height: 36, borderRadius: 10,
            background: "linear-gradient(135deg, #5A8DEE, #42E695)",
            display: "flex", alignItems: "center", justifyContent: "center",
            fontSize: 17, boxShadow: "0 3px 12px rgba(90,141,238,0.4)",
          }}>🤖</div>
          <div>
            <div style={{ fontFamily: "'Syne',sans-serif", fontWeight: 800, fontSize: 14, color: "var(--text-primary)" }}>
              AI Finance Mentor
            </div>
            <div style={{ fontSize: 11, color: "var(--text-secondary)" }}>
              {processedEntries.length} entries loaded
              {processedEntries.length < (entries?.length || 0) &&
                <span style={{ color: "var(--accent-yellow)", marginLeft: 5 }}>
                  (last {processedEntries.length} of {entries.length})
                </span>
              }
            </div>
          </div>
        </div>
        {chatHistory.length > 0 && (
          <button onClick={() => setChatHistory([])}
            style={{ background: "rgba(255,255,255,0.07)", border: "1px solid var(--border)", borderRadius: 8, padding: "4px 12px", color: "var(--text-secondary)", cursor: "pointer", fontSize: 11, fontFamily: "'Syne',sans-serif", fontWeight: 600 }}>
            Clear
          </button>
        )}
      </div>

      {/* ── ERROR BANNER ── */}
      {error && (
        <div style={{ padding: "8px 16px", background: "rgba(252,129,129,0.12)", borderBottom: "1px solid rgba(252,129,129,0.25)", color: "var(--accent-red)", fontSize: 12, display: "flex", alignItems: "center", gap: 6 }}>
          ⚠️ {error}
          <button onClick={() => setError(null)} style={{ marginLeft: "auto", background: "none", border: "none", color: "var(--accent-red)", cursor: "pointer", fontSize: 14 }}>×</button>
        </div>
      )}

      {/* ── CHAT MESSAGES ── */}
      <div style={{ flex: 1, overflowY: "auto", padding: "14px", display: "flex", flexDirection: "column", gap: 10 }}>
        {chatHistory.length === 0 ? (
          <div style={{ flex: 1, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", textAlign: "center", padding: "20px 0" }}>
            <div style={{ fontSize: 42, marginBottom: 12 }}>💬</div>
            <div style={{ fontFamily: "'Syne',sans-serif", fontWeight: 700, fontSize: 15, color: "var(--text-primary)", marginBottom: 6 }}>
              Ask your AI Finance Mentor
            </div>
            <div style={{ fontSize: 12, color: "var(--text-secondary)", marginBottom: 20 }}>
              Get insights, summaries, and advice from your data
            </div>
            {/* Quick prompts */}
            <div style={{ display: "flex", flexWrap: "wrap", gap: 7, justifyContent: "center", maxWidth: 420 }}>
              {QUICK_PROMPTS.map((p, i) => (
                <button key={i} onClick={() => sendMessage(p)}
                  style={{
                    padding: "7px 14px", borderRadius: 20, border: "1px solid var(--border)",
                    background: "var(--bg-input)", color: "var(--text-secondary)",
                    fontSize: 12, cursor: "pointer", fontFamily: "'Syne',sans-serif", fontWeight: 600,
                    transition: "all 0.15s",
                  }}
                  onMouseEnter={e => { e.currentTarget.style.borderColor = "#5A8DEE"; e.currentTarget.style.color = "#5A8DEE"; e.currentTarget.style.background = "rgba(90,141,238,0.1)"; }}
                  onMouseLeave={e => { e.currentTarget.style.borderColor = "var(--border)"; e.currentTarget.style.color = "var(--text-secondary)"; e.currentTarget.style.background = "var(--bg-input)"; }}>
                  {p}
                </button>
              ))}
            </div>
          </div>
        ) : (
          chatHistory.map((msg, i) => (
            <div key={i} style={{
              alignSelf: msg.sender === "user" ? "flex-end" : "flex-start",
              maxWidth: "78%",
              animation: "fadeUp 0.2s ease",
            }}>
              {/* Sender label */}
              <div style={{ fontSize: 10, color: "var(--text-muted)", marginBottom: 3, paddingLeft: msg.sender === "user" ? 0 : 4, textAlign: msg.sender === "user" ? "right" : "left", fontFamily: "'Syne',sans-serif", fontWeight: 700, letterSpacing: "0.04em" }}>
                {msg.sender === "user" ? "YOU" : "🤖 AI"} · {msg.time}
              </div>
              <div style={{
                padding: "10px 14px",
                borderRadius: msg.sender === "user" ? "16px 16px 4px 16px" : "16px 16px 16px 4px",
                background: msg.sender === "user"
                  ? "linear-gradient(135deg, #5A8DEE, #42E695)"
                  : "var(--bg-input)",
                color: msg.sender === "user" ? "#fff" : "var(--text-primary)",
                fontSize: 13.5,
                lineHeight: 1.65,
                border: msg.sender === "user" ? "none" : "1px solid var(--border)",
                boxShadow: msg.sender === "user" ? "0 4px 14px rgba(90,141,238,0.3)" : "none",
                wordBreak: "break-word",
              }}>
                <ReactMarkdown
                  components={{
                    strong: ({ node, ...props }) => (
                      <strong style={{ color: msg.sender === "user" ? "#fff" : "var(--accent-blue)", fontWeight: 700 }} {...props} />
                    ),
                    li: ({ node, ...props }) => <li style={{ marginBottom: 3 }} {...props} />,
                    table: ({ node, ...props }) => (
                      <div style={{ overflowX: "auto", marginTop: 6 }}>
                        <table style={{ borderCollapse: "collapse", fontSize: 12, width: "100%" }} {...props} />
                      </div>
                    ),
                    th: ({ node, ...props }) => (
                      <th style={{ padding: "5px 10px", border: "1px solid var(--border)", background: "rgba(255,255,255,0.06)", fontFamily: "'Syne',sans-serif", fontSize: 11, textTransform: "uppercase" }} {...props} />
                    ),
                    td: ({ node, ...props }) => (
                      <td style={{ padding: "5px 10px", border: "1px solid var(--border)" }} {...props} />
                    ),
                    code: ({ node, ...props }) => (
                      <code style={{ background: "rgba(255,255,255,0.08)", padding: "1px 5px", borderRadius: 4, fontSize: 12 }} {...props} />
                    ),
                  }}
                >
                  {msg.text}
                </ReactMarkdown>
              </div>
            </div>
          ))
        )}

        {loading && (
          <div style={{ alignSelf: "flex-start", display: "flex", alignItems: "center", gap: 8, padding: "10px 14px", borderRadius: "16px 16px 16px 4px", background: "var(--bg-input)", border: "1px solid var(--border)", fontSize: 13, color: "var(--text-secondary)" }}>
            <div style={{ display: "flex", gap: 4 }}>
              {[0,1,2].map(i => (
                <div key={i} style={{ width: 7, height: 7, borderRadius: "50%", background: "#5A8DEE", animation: `bounce 1s ease-in-out ${i * 0.16}s infinite` }} />
              ))}
            </div>
            AI is thinking…
          </div>
        )}
        <div ref={chatEndRef} />
      </div>

      {/* ── QUICK PROMPTS (when chat has messages) ── */}
      {chatHistory.length > 0 && !loading && (
        <div style={{ padding: "6px 14px", borderTop: "1px solid var(--border)", display: "flex", gap: 6, overflowX: "auto" }}>
          {QUICK_PROMPTS.slice(0, 4).map((p, i) => (
            <button key={i} onClick={() => sendMessage(p)}
              style={{
                padding: "4px 11px", borderRadius: 20, border: "1px solid var(--border)",
                background: "var(--bg-input)", color: "var(--text-secondary)",
                fontSize: 11, cursor: "pointer", fontFamily: "'Syne',sans-serif", fontWeight: 600,
                whiteSpace: "nowrap", flexShrink: 0, transition: "all 0.15s",
              }}>
              {p}
            </button>
          ))}
        </div>
      )}

      {/* ── INPUT ── */}
      <div style={{ padding: "12px 14px", borderTop: "1px solid var(--border)", background: "var(--bg-surface)", borderRadius: "0 0 18px 18px", display: "flex", gap: 8, alignItems: "flex-end" }}>
        <textarea
          ref={inputRef}
          rows={1}
          value={userMessage}
          onChange={e => {
            setUserMessage(e.target.value);
            e.target.style.height = "auto";
            e.target.style.height = Math.min(e.target.scrollHeight, 100) + "px";
          }}
          placeholder="Ask about your finances…"
          onKeyDown={handleKeyDown}
          disabled={loading}
          style={{
            flex: 1, padding: "10px 14px", borderRadius: 12,
            border: "1px solid var(--border)",
            background: "var(--bg-input)",
            color: "var(--text-primary)",
            fontSize: 13.5, outline: "none",
            resize: "none", overflowY: "hidden",
            fontFamily: "'DM Sans',sans-serif",
            lineHeight: 1.5, maxHeight: 100,
            transition: "border-color 0.2s",
          }}
          onFocus={e => e.target.style.borderColor = "#5A8DEE"}
          onBlur={e => e.target.style.borderColor = "var(--border)"}
        />
        <button
          onClick={() => sendMessage()}
          disabled={loading || !userMessage.trim()}
          style={{
            width: 42, height: 42, borderRadius: 12, border: "none", cursor: "pointer",
            background: loading || !userMessage.trim()
              ? "var(--bg-input)"
              : "linear-gradient(135deg, #5A8DEE, #42E695)",
            color: loading || !userMessage.trim() ? "var(--text-muted)" : "#fff",
            fontSize: 18, display: "flex", alignItems: "center", justifyContent: "center",
            flexShrink: 0, transition: "all 0.2s",
            boxShadow: loading || !userMessage.trim() ? "none" : "0 4px 14px rgba(90,141,238,0.4)",
          }}>
          {loading ? (
            <div style={{ width: 16, height: 16, border: "2px solid rgba(255,255,255,0.3)", borderTopColor: "#5A8DEE", borderRadius: "50%", animation: "spin 0.7s linear infinite" }} />
          ) : "➤"}
        </button>
      </div>

      <style>{`
        @keyframes bounce {
          0%, 100% { transform: translateY(0); opacity: 0.5; }
          50%       { transform: translateY(-5px); opacity: 1; }
        }
        @keyframes spin {
          to { transform: rotate(360deg); }
        }
        @keyframes fadeUp {
          from { opacity: 0; transform: translateY(8px); }
          to   { opacity: 1; transform: translateY(0); }
        }
      `}</style>
    </div>
  );
};

export default ChatAI;